def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    objects = Counter()
    for row in grid:
        prev = background
        for v in row + [background]:
            if v != prev:
                if prev != background:
                    objects[prev] += 1
                prev = v
    vals = []
    for color in sorted(objects, reverse=True):
        vals.extend([color] * objects[color])
    width = 3
    vals += [0] * ((-len(vals)) % width)
    return [vals[i:i + width] for i in range(0, len(vals), width)]
